const KEY='adab_students_demo_v2', AU='adab_teacher_demo_v2', PUB='adab_content_publication_v2', NOTICES='adab_notices_demo_v2', CLOUD_T='adab_cloud_teacher_token_v1';
const API_BASE='/api';
let CLOUD_STUDENTS=null;
async function cloudJson(path,opts={}){const headers={'content-type':'application/json',...(opts.headers||{})};const token=sessionStorage.getItem(CLOUD_T);if(token)headers.authorization='Bearer '+token;const r=await fetch(API_BASE+path,{...opts,headers});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'api_error');return d}
async function loadCloudStudents(){try{const d=await cloudJson('/teacher/students');CLOUD_STUDENTS=d.students;localStorage.setItem(KEY,JSON.stringify(CLOUD_STUDENTS));return true}catch(e){return false}}

