/* ===== 2.0 CLOUD BRIDGE: shared teacher workspace ===== */
const _syncTeacherCloud20=syncTeacherCloud;
syncTeacherCloud=async function(){
  if(!teacherCloudReady())return false;
  try{
    const first=await _syncTeacherCloud20();
    if(!first || CLOUD_CONTENT.length<CONTENT.length){
      const payload=CONTENT.map(x=>({id:x.id,title:x.title,axis:x.axis,number:x.number,category:x.category,file:x.file,kind:x.category,axisLabel:x.axisLabel,categoryLabel:x.categoryLabel}));
      await cloudJson('/teacher/content/bootstrap',{method:'POST',body:JSON.stringify({items:payload})});
      return await _syncTeacherCloud20();
    }
    return first;
  }catch(e){return false}
};
loadCloudStudents=async function(){return await syncTeacherCloud()};

let CLOUD_CONTENT=[], CLOUD_MISSIONS=[], CLOUD_MESSAGES=[], CLOUD_NOTES=[], CLOUD_NOTICES=[], CLOUD_TESTS=[], CLOUD_MEDIA=[], CLOUD_SETTINGS=[], CLOUD_ACTIVITY=[];
const AXIS_LABELS=['','شعر الحماسة','المنزع العقلي','رسالة الغفران','مغامرة رأس المملوك جابر','حدث أبو هريرة قال'];
function teacherCloudReady(){return !!sessionStorage.getItem(CLOUD_T)}
function cloudContentView(x){
  const base=CONTENT.find(c=>String(c.id)===String(x.id));
  return {...x,category:base?.category||({lesson:'lessons',training:'training',research:'research'})[x.kind]||x.kind,categoryLabel:base?.categoryLabel||({lesson:'الدروس',training:'التدريبات',research:'البحوث'})[x.kind]||x.kind,axis:Number(x.axis_no||base?.axis||1),axisLabel:AXIS_LABELS[Number(x.axis_no||base?.axis||1)]||'',number:Number(x.order_index||base?.number||0),file:base?.file||null};
}
async function syncTeacherCloud(){
  if(!teacherCloudReady())return false;
  try{
    const [st,co,mi,ms,no,an,te,me,se,lg]=await Promise.all([
      cloudJson('/teacher/students'),cloudJson('/teacher/content'),cloudJson('/teacher/missions'),cloudJson('/teacher/messages'),cloudJson('/teacher/notes'),cloudJson('/teacher/announcements'),cloudJson('/teacher/tests'),cloudJson('/teacher/media'),cloudJson('/teacher/settings'),cloudJson('/teacher/activity')
    ]);
    CLOUD_STUDENTS=st.students||[]; CLOUD_CONTENT=(co.items||[]).map(cloudContentView); CLOUD_MISSIONS=mi.missions||[]; CLOUD_MESSAGES=ms.messages||[]; CLOUD_NOTES=no.notes||[]; CLOUD_NOTICES=an.announcements||[]; CLOUD_TESTS=te.tests||[]; CLOUD_MEDIA=me.media||[]; CLOUD_SETTINGS=se.settings||[]; CLOUD_ACTIVITY=lg.logs||[];
    localStorage.setItem(KEY,JSON.stringify(CLOUD_STUDENTS)); localStorage.setItem(PUB,JSON.stringify(Object.fromEntries(CLOUD_CONTENT.map(x=>[x.id,x.status==='published']))));
    localStorage.setItem(TESTS,JSON.stringify(CLOUD_TESTS.map(t=>({...t,published:t.status==='published',axisLabel:AXIS_LABELS[t.axis_no]||'',questions:t.questions||[],results:(t.answers||[]).reduce((a,x)=>{let r=a.find(z=>z.studentId===x.student_id);if(!r){r={studentId:x.student_id,answers:[],studentName:(CLOUD_STUDENTS.find(s=>String(s.id)===String(x.student_id))||{}).name||'تلميذ',date:x.submitted_at};a.push(r)}r.answers.push(x.answer_text);return a},[])}))));
    localStorage.setItem(MEDIA,JSON.stringify(CLOUD_MEDIA.map(m=>({...m,published:m.status==='published',type:m.type||'link',axisLabel:AXIS_LABELS[m.axis_no]||''}))));
    localStorage.setItem(NOTES,JSON.stringify(CLOUD_NOTES.map(n=>({id:n.id,studentId:n.student_id,studentName:n.student_name||'',type:n.note_type,text:n.note_text,contextId:n.linked_content_id,contextTitle:cloudContentView(CLOUD_CONTENT.find(c=>c.id===n.linked_content_id)||{}).title||'',reply:n.student_reply?{text:n.student_reply,date:n.replied_at}:null,date:n.created_at}))));
    localStorage.setItem(NOTICES,JSON.stringify(CLOUD_NOTICES.map(n=>({id:n.id,type:n.kind,typeLabel:n.kind==='announcement'?'إعلان عام':'تنبيه',title:n.title,text:n.body,target:n.target_student_id?'student:'+n.target_student_id:'all',studentId:n.target_student_id,contentId:n.linked_content_id,date:n.created_at}))));
    localStorage.setItem(LOG,JSON.stringify(CLOUD_ACTIVITY.map(x=>({date:x.created_at,action:x.action,detail:x.details_json||'',level:x.level||'info'}))));
    return true;
  }catch(e){return false}
}
function list(){return CLOUD_STUDENTS||JSON.parse(localStorage.getItem(KEY)||'[]')}
function pubMap(){if(CLOUD_CONTENT.length)return Object.fromEntries(CLOUD_CONTENT.map(x=>[x.id,x.status==='published']));let v=JSON.parse(localStorage.getItem(PUB)||'null');if(!v){v={};CONTENT.forEach(x=>v[x.id]=true);localStorage.setItem(PUB,JSON.stringify(v))}return v}
function isPublished(cid){const x=CLOUD_CONTENT.find(c=>String(c.id)===String(cid));return x?x.status==='published':!!pubMap()[cid]}
async function setPublished(cid,val){if(teacherCloudReady()){try{const d=await cloudJson('/teacher/content/'+encodeURIComponent(cid),{method:'PATCH',body:JSON.stringify({status:val?'published':'draft'})});const i=CLOUD_CONTENT.findIndex(x=>String(x.id)===String(cid));if(i>=0)CLOUD_CONTENT[i]={...CLOUD_CONTENT[i],status:val?'published':'draft'};localStorage.setItem(PUB,JSON.stringify(Object.fromEntries(CLOUD_CONTENT.map(x=>[x.id,x.status==='published']))));await syncTeacherCloud();renderAll();return d}catch(e){}}const m=pubMap();m[cid]=val;localStorage.setItem(PUB,JSON.stringify(m))}
function contentById(cid){return CLOUD_CONTENT.find(x=>String(x.id)===String(cid))||CONTENT.find(x=>String(x.id)===String(cid))}
function contentPath(c){return c?(c.file?`${c.category}__${c.file}`:'/content/'+encodeURIComponent(c.id)):''}
function fillMissionFields(){const ss=$('missionStudent'),cs=$('missionContent');if(ss){const us=list();ss.innerHTML='<option value="">اختر تلميذًا</option>'+us.filter(u=>u.status!=='suspended').map(u=>`<option value="${u.id}">${u.name} · ${u.phone}</option>`).join('')}if(cs)cs.innerHTML='<option value="">اختر محتوى منشورًا</option>'+CLOUD_CONTENT.filter(x=>x.status==='published').map(x=>`<option value="${x.id}">${x.title}</option>`).join('')}
function fillNoticeContent(){const sel=$('noticeContent');if(!sel)return;sel.innerHTML='<option value="">دون ربط</option>'+CLOUD_CONTENT.filter(x=>x.status==='published').map(x=>`<option value="${x.id}">${x.title}</option>`).join('')}
function fillTestStudents(){const s=$('testStudent'),n=$('noteStudent'),opts=list().filter(u=>u.status!=='suspended').map(u=>`<option value="${u.id}">${u.name} · ${u.phone}</option>`).join('');if(s)s.innerHTML='<option value="">للنشر العام</option>'+opts;if(n)n.innerHTML='<option value="">اختر تلميذًا</option>'+opts}
function legacyContentForCloud(){const cloudById=new Map(CLOUD_CONTENT.map(x=>[String(x.id),x]));return CONTENT.map(x=>{const c=cloudById.get(String(x.id));return c?c:{...x,status:'published',source_mode:'static'} }).concat(CLOUD_CONTENT.filter(x=>!CONTENT.some(c=>String(c.id)===String(x.id))))} function renderContent(){const q=($('contentSearch')?.value||'').trim().toLowerCase(),type=$('contentTypeFilter')?.value||'all',axis=$('contentAxisFilter')?.value||'all';const source=legacyContentForCloud();const arr=source.filter(x=>(type==='all'||x.category===type)&&(axis==='all'||String(x.axis)===axis)&&(!q||(`${x.title} ${x.axisLabel} ${x.categoryLabel}`).toLowerCase().includes(q)));$('allContentTotal').textContent=source.length;$('publishedContentTotal').textContent=source.filter(x=>x.status==='published').length;let box=$('contentTable');if(!box)return;box.innerHTML=arr.length?arr.map(x=>`<div class="admin-content-row"><div class="content-meta"><span class="content-kind">${x.categoryLabel}</span><b>${x.title}</b><small>المحور ${x.axis} · ${x.axisLabel} · رقم ${String(x.number||0).padStart(2,'0')} · ${x.source_mode==='dynamic'?'محتوى جديد':'محتوى أساسي'}</small></div><div class="content-control"><span class="publish-status ${x.status==='published'?'is-published':'is-hidden'}">${x.status==='published'?'منشور':'مخفي'}</span><label class="switch"><input type="checkbox" data-content-id="${x.id}" ${x.status==='published'?'checked':''}><span></span></label>${x.source_mode==='dynamic'?`<button class="ghost-btn" data-edit-content="${x.id}">تحرير</button>`:''}<a class="ghost-btn" href="${contentPath(x)}" target="_blank">معاينة</a></div></div>`).join(''):'<div class="empty-state">لا توجد موارد توافق البحث.</div>';
  box.querySelectorAll('input[type=checkbox]').forEach(ch=>ch.onchange=async()=>{await setPublished(ch.dataset.contentId,ch.checked);renderContent()});
  box.querySelectorAll('[data-edit-content]').forEach(b=>b.onclick=async()=>{const x=CLOUD_CONTENT.find(z=>String(z.id)===String(b.dataset.editContent));if(!x)return;const title=prompt('عنوان المحتوى:',x.title);if(title===null)return;const summary=prompt('ملخص المحتوى:',x.summary||'');const body=x.source_mode==='dynamic'?prompt('محتوى HTML (اختياري):',x.body_html||''):x.body_html;try{await cloudJson('/teacher/content/'+encodeURIComponent(x.id),{method:'PATCH',body:JSON.stringify({title:title.trim(),summary:summary??x.summary,body_html:body||null})});await syncTeacherCloud();renderAll()}catch(e){alert('تعذر حفظ التعديل.')}})
}
function ensureContentCreator(){const sec=$('content');if(!sec||$('contentCreateForm'))return;const panel=document.createElement('div');panel.className='admin-panel wide';panel.innerHTML=`<div class="section-title-row"><h2>إنشاء محتوى جديد</h2><span class="status-pill">2.0</span></div><form id="contentCreateForm" class="notice-form"><div class="admin-grid"><label>النوع<select id="newContentKind"><option value="lesson">درس</option><option value="training">تدريب</option><option value="research">بحث</option></select></label><label>المحور<select id="newContentAxis"><option value="1">شعر الحماسة</option><option value="2">المنزع العقلي</option><option value="3">رسالة الغفران</option><option value="4">مغامرة رأس المملوك جابر</option><option value="5">حدث أبو هريرة قال</option></select></label></div><label>العنوان<input id="newContentTitle" required></label><label>ملخص مختصر<textarea id="newContentSummary" rows="2"></textarea></label><label>محتوى HTML<textarea id="newContentBody" rows="7" placeholder="يمكنك كتابة محتوى الدرس هنا…"></textarea></label><label class="check-row"><input id="newContentPublish" type="checkbox"> نشره مباشرة</label><button class="primary-btn" type="submit">إضافة المحتوى</button><div id="newContentFeedback" class="form-feedback"></div></form>`;sec.querySelector('.admin-panel.wide')?.after(panel);$('contentCreateForm').onsubmit=async e=>{e.preventDefault();try{await cloudJson('/teacher/content',{method:'POST',body:JSON.stringify({kind:$('newContentKind').value,axis_no:Number($('newContentAxis').value),title:$('newContentTitle').value.trim(),summary:$('newContentSummary').value.trim(),body_html:$('newContentBody').value,status:$('newContentPublish').checked?'published':'draft',order_index:CLOUD_CONTENT.length+1,source_mode:'dynamic'})});e.target.reset();$('newContentFeedback').textContent='تمت إضافة المحتوى.';await syncTeacherCloud();renderAll();setTimeout(()=>$('newContentFeedback').textContent='',2200)}catch(err){$('newContentFeedback').textContent='تعذر إضافة المحتوى الآن.'}}}
async function renderMissions(){const box=$('missionTable');if(!box)return;const rows=CLOUD_MISSIONS||[];$('missionTotal').textContent=rows.length;$('missionSubmissionsTotal').textContent=rows.filter(m=>m.status==='submitted').length;box.innerHTML=rows.length?rows.map(m=>{const c=contentById(m.content_id),st=m.status||'new',u=list().find(x=>String(x.id)===String(m.student_id));return `<div class="admin-mission-row"><div><span class="notice-kind">${st==='submitted'?'إنجاز ينتظر المراجعة':st==='reviewed'?'تمت المراجعة':'مهمة جارية'}</span><b>${m.title}</b><p>${m.instructions}</p><small>${u?.name||m.student_name||''} · ${c?.title||'دون محتوى'} · ${m.created_at||''}</small>${c?`<a class="notice-link" href="${contentPath(c)}" target="_blank">↗ فتح المحتوى</a>`:''}${m.submission_text?`<div class="mission-submission"><strong>إنجاز التلميذ:</strong><p>${m.submission_text}</p><small>${m.submitted_at||''}</small></div>`:'<div class="muted">لم يرسل التلميذ إنجازه بعد.</div>'}${m.feedback?`<div class="mission-feedback"><strong>ملاحظتك السابقة:</strong><p>${m.feedback}</p></div>`:''}</div><div class="mission-actions">${m.submission_text&&st!=='reviewed'?`<button class="primary-btn mission-review-btn" data-id="${m.id}">مراجعة الإنجاز</button>`:''}</div></div>`}).join(''):'<div class="empty-state">لا توجد مهمات مسندة بعد.</div>';box.querySelectorAll('.mission-review-btn').forEach(b=>b.onclick=()=>reviewMissionCloud(b.dataset.id))}
async function reviewMissionCloud(mid){const m=CLOUD_MISSIONS.find(x=>String(x.id)===String(mid));if(!m)return;const feedback=prompt('اكتب ملاحظة الأستاذ على إنجاز التلميذ:','أحسنت. واصل العمل مع مزيد من الدقة في الاستدلال والتعليل.');if(feedback===null)return;try{await cloudJson('/teacher/missions/'+encodeURIComponent(mid)+'/review',{method:'POST',body:JSON.stringify({feedback:feedback.trim()||'تمت مراجعة إنجازك. واصل العمل.'})});await cloudJson('/teacher/announcements',{method:'POST',body:JSON.stringify({title:'تمت مراجعة مهمتك: '+m.title,body:feedback.trim()||'تمت مراجعة إنجازك.',kind:'task-review',target_student_id:m.student_id,published:1,linked_content_id:m.content_id||null})});await syncTeacherCloud();renderAll();alert('تم حفظ المراجعة وإشعار التلميذ.') }catch(e){alert('تعذر حفظ المراجعة الآن.')}}
function renderMessages(us){const rows=CLOUD_MESSAGES.filter(m=>m.sender_type==='student');$('messageTable').innerHTML=rows.length?rows.map(m=>`<div class="admin-message-row"><div><b>${(list().find(u=>String(u.id)===String(m.sender_id))||{}).name||'تلميذ'}</b><small>${(list().find(u=>String(u.id)===String(m.sender_id))||{}).phone||''} · ${m.created_at||''}</small><p>${m.body}</p></div><button class="ghost-btn reply-btn" data-id="${m.sender_id}">الرد</button></div>`).join(''):'<div class="empty-state">لا توجد رسائل من التلاميذ.</div>';$('messageSectionCount').textContent=rows.filter(m=>!m.is_read).length;boxReplyHandlers()}
function boxReplyHandlers(){$('messageTable')?.querySelectorAll('.reply-btn').forEach(b=>b.onclick=()=>replyCloud(b.dataset.id))}
async function replyCloud(studentId){const text=prompt('اكتب رد الأستاذ:');if(!text)return;try{await cloudJson('/teacher/messages',{method:'POST',body:JSON.stringify({student_id:studentId,body:text})});await syncTeacherCloud();renderAll();alert('تم إرسال الرد إلى فضاء التلميذ.')}catch(e){alert('تعذر إرسال الرد الآن.')}}
function renderNotices(){const arr=CLOUD_NOTICES||[];$('noticeTotal').textContent=arr.length;const box=$('noticeTable');if(!box)return;box.innerHTML=arr.length?arr.map(n=>`<div class="admin-notice-row"><div><span class="notice-kind">${n.kind||'إعلان'}</span><b>${n.title}</b><p>${n.body}</p><small>${n.target_student_id?'تلميذ محدد':'جميع التلاميذ'} · ${n.created_at||''}</small></div></div>`).join(''):'<div class="empty-state">لا توجد إعلانات منشورة بعد.</div>'}
async function createCloudNoticeFromForm(e){e.preventDefault();const n={kind:$('noticeType').value,title:$('noticeTitle').value.trim(),body:$('noticeText').value.trim(),target_student_id:null,linked_content_id:$('noticeContent').value||null,published:1};if(!n.title||!n.body)return;try{await cloudJson('/teacher/announcements',{method:'POST',body:JSON.stringify(n)});e.target.reset();$('noticeFeedback').textContent='تم نشر الإعلان، وسيظهر للتلاميذ.';await syncTeacherCloud();renderAll();setTimeout(()=>$('noticeFeedback').textContent='',2200)}catch(err){$('noticeFeedback').textContent='تعذر نشر الإعلان الآن.'}}
function renderTests(){const a=CLOUD_TESTS||[];const box=$('testTable');$('testTotal').textContent=a.length;if(!box)return;box.innerHTML=a.length?a.map(t=>`<div class="admin-test-row"><div><span class="notice-kind">اختبار قصير · ${AXIS_LABELS[t.axis_no]||''}</span><b>${t.title}</b><p>${t.description||''}</p><small>${(t.questions||[]).length} أسئلة · ${t.status==='published'?'منشور':'مخفي'} · ${(t.answers||[]).length} إجابة</small>${(t.answers||[]).map(r=>`<div class="mission-submission"><strong>${(list().find(u=>String(u.id)===String(r.student_id))||{}).name||'تلميذ'}</strong><p>${r.answer_text}</p><small>${r.submitted_at||''}</small></div>`).join('')}</div></div>`).join(''):'<div class="empty-state">لا توجد اختبارات منشأة بعد.</div>'}
async function createCloudTest(e){e.preventDefault();const qs=$('testQuestions').value.split('\n').map(x=>x.trim()).filter(Boolean).map(prompt=>({prompt,points:1}));if(!qs.length)return;try{await cloudJson('/teacher/tests',{method:'POST',body:JSON.stringify({title:$('testTitle').value.trim(),axis_no:Number($('testAxis').value),description:$('testInstructions').value.trim(),questions:qs,student_id:$('testStudent').value||null,published:$('testPublish').checked,audience:$('testStudent').value?'assigned':'public'})});e.target.reset();$('testPublish').checked=true;$('testFeedback').textContent='تم حفظ الاختبار في قاعدة البيانات.';await syncTeacherCloud();renderAll();setTimeout(()=>$('testFeedback').textContent='',2000)}catch(err){$('testFeedback').textContent='تعذر حفظ الاختبار الآن.'}}
function renderMedia(){const a=CLOUD_MEDIA||[],box=$('mediaTable');$('mediaTotal').textContent=a.length;if(!box)return;box.innerHTML=a.length?a.map(m=>`<div class="admin-media-row"><div><span class="notice-kind">${m.type||'رابط'}</span><b>${m.title}</b><p>${m.description||''}</p><small>${AXIS_LABELS[m.axis_no]||''} · ${m.status==='published'?'ظاهر للتلميذ':'مخفي'}</small><br><a class="notice-link" href="${m.url}" target="_blank" rel="noopener">فتح المورد ↗</a></div></div>`).join(''):'<div class="empty-state">لم تُضف موارد مساندة بعد.</div>'}
async function createCloudMedia(e){e.preventDefault();try{await cloudJson('/teacher/media',{method:'POST',body:JSON.stringify({title:$('mediaTitle').value.trim(),url:$('mediaUrl').value.trim(),axis_no:Number($('mediaAxis').value),description:$('mediaDesc').value.trim(),status:$('mediaPublish').checked?'published':'draft'})});e.target.reset();$('mediaPublish').checked=true;$('mediaFeedback').textContent='تمت إضافة المورد.';await syncTeacherCloud();renderAll();setTimeout(()=>$('mediaFeedback').textContent='',2000)}catch(err){$('mediaFeedback').textContent='تعذر إضافة المورد الآن.'}}
async function createCloudNote(e){e.preventDefault();const uid=$('noteStudent').value;if(!uid)return;try{await cloudJson('/teacher/notes',{method:'POST',body:JSON.stringify({student_id:uid,note_type:$('noteType').value,linked_content_id:$('noteContext').value||null,note_text:$('noteText').value.trim()})});e.target.reset();$('noteFeedback').textContent='حُفظت الملاحظة وأُشعر التلميذ بها.';await syncTeacherCloud();renderAll();setTimeout(()=>$('noteFeedback').textContent='',2200)}catch(err){$('noteFeedback').textContent='تعذر حفظ الملاحظة الآن.'}}
function renderNotes(){const a=CLOUD_NOTES||[],box=$('noteTable');$('noteTotal').textContent=a.length;if(!box)return;box.innerHTML=a.length?a.map(n=>`<div class="admin-note-row"><span class="note-chip">${({strength:'نقطة قوة',support:'ما يحتاج إلى دعم',next:'الخطوة التالية',general:'ملاحظة عامة'})[n.note_type]||'ملاحظة'}</span><b>${n.student_name||'تلميذ'}</b><p>${n.note_text}</p><small>${n.created_at||''}</small>${n.student_reply?`<div class="mission-feedback"><strong>ردّ التلميذ:</strong><p>${n.student_reply}</p><small>${n.replied_at||''}</small></div>`:'<div class="muted">لم يردّ التلميذ بعد.</div>'}</div>`).join(''):'<div class="empty-state">لا توجد ملاحظات بعد.</div>'}
async function createCloudMission(e){e.preventDefault();const studentId=$('missionStudent').value,contentId=$('missionContent').value,title=$('missionTitle').value.trim(),instructions=$('missionText').value.trim();if(!studentId||!contentId||!title||!instructions){$('missionFeedback').textContent='يرجى استكمال بيانات المهمة.';return}try{await cloudJson('/teacher/missions',{method:'POST',body:JSON.stringify({student_id:studentId,content_id:contentId,title,instructions})});if($('missionNotify').checked){await cloudJson('/teacher/announcements',{method:'POST',body:JSON.stringify({title:'مهمة جديدة: '+title,body:'أسند إليك الأستاذ مهمة مرتبطة بالمحتوى المختار.',kind:'task',target_student_id:studentId,published:1,linked_content_id:contentId})})}e.target.reset();$('missionNotify').checked=true;$('missionFeedback').textContent='تم إسناد المهمة وستظهر للتلميذ.';await syncTeacherCloud();renderAll();setTimeout(()=>$('missionFeedback').textContent='',2200)}catch(err){$('missionFeedback').textContent='تعذر إسناد المهمة الآن.'}}
async function saveCloudSettings(e){e.preventDefault();const vals={notice:$('setNotice').checked,mission:$('setMission').checked,review:$('setReview').checked,platformName:$('setPlatformName').value.trim()||'الأدب العربي في البكالوريا'};try{for(const [k,v] of Object.entries(vals))await cloudJson('/teacher/settings',{method:'POST',body:JSON.stringify({setting_key:k,setting_value:String(v)})});$('settingsFeedback').textContent='تم حفظ الإعدادات المشتركة.';await syncTeacherCloud();setTimeout(()=>$('settingsFeedback').textContent='',1800)}catch(e){$('settingsFeedback').textContent='تعذر حفظ الإعدادات الآن.'}}
function renderSettings(){const m=Object.fromEntries((CLOUD_SETTINGS||[]).map(x=>[x.setting_key,x.setting_value]));if($('setNotice'))$('setNotice').checked=m.notice!=='false';if($('setMission'))$('setMission').checked=m.mission!=='false';if($('setReview'))$('setReview').checked=m.review!=='false';if($('setPlatformName'))$('setPlatformName').value=m.platformName||'الأدب العربي في البكالوريا';if($('setTeacherUser'))$('setTeacherUser').value='أستاذ المنصة';}
function renderSecurity(){const a=CLOUD_ACTIVITY||[],box=$('securityLog');if(!box)return;const q=($('logSearch')?.value||'').trim().toLowerCase(),lv=$('logLevel')?.value||'all';const rows=a.filter(x=>(lv==='all'||x.level===lv)&&(!q||(`${x.action} ${x.details_json||''}`).toLowerCase().includes(q)));box.innerHTML=rows.length?rows.slice(0,200).map(x=>`<div class="admin-log-row log-${x.level||'info'}"><div><b>${x.action}</b><small>${x.details_json||''}</small></div><small>${x.created_at||''}</small></div>`).join(''):'<div class="empty-state">لا توجد عمليات مطابقة.</div>';if($('logCount'))$('logCount').textContent=`${rows.length} عملية`}
const _renderAll20=renderAll; renderAll=function(){_renderAll20();renderContent();renderMissions();renderTests();renderMedia();renderNotes();renderNotices();renderSettings();renderSecurity();fillMissionFields();fillNoticeContent();fillTestStudents();ensureContentCreator()};
$('missionForm').onsubmit=createCloudMission;
$('testForm').onsubmit=createCloudTest;
$('mediaForm').onsubmit=createCloudMedia;
$('noticeForm').onsubmit=createCloudNoticeFromForm;
$('noteForm').onsubmit=createCloudNote;
$('settingsForm').onsubmit=saveCloudSettings;
if(teacherCloudReady())setTimeout(async()=>{if(await syncTeacherCloud())renderAll()},0);
